//! 🔲️ Regular two-dimensional constraints with explicitly typed bitmap, path and child media.
use super::*;
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabase,SqliteSnapshotControl,SqliteSnapshotPhase,SnapshotEncoding,validate_sqlite_database_schema,artifact::{Cell,Projection,Reconstruction,NativeEncodingBound,FloatColumn,FloatRow,insert_ieee754,insert_key_ieee754}}};
use std::collections::{BTreeMap,BTreeSet};
fn ordinal(n:usize)->Result<i64,String>{i64::try_from(n).map_err(|_|"grid2d ordinal overflow".into())}
fn floats(t:&str)->&'static[FloatColumn]{match t{"wfc_grid2d_document"=>&[FloatColumn::Binary64(5),FloatColumn::Binary64(6)],"wfc_grid2d_tile"=>&[FloatColumn::Binary64(5)],"wfc_grid2d_path"=>&[FloatColumn::Binary64(3)],"wfc_grid2d_segment"=>&[FloatColumn::Binary64(4),FloatColumn::Binary64(5),FloatColumn::Binary64(6),FloatColumn::Binary64(7),FloatColumn::Binary64(8),FloatColumn::Binary64(9)],_=>&[]}}
fn identity(r:FloatRow<'_>,n:usize)->Result<(),String>{if r.rowid<=0||r.integer(0)?!=r.rowid||r.values.len()!=n{return Err("grid2d entity identity or columns differ".into())}Ok(())}
fn word(r:FloatRow<'_>,i:usize)->Result<u32,String>{u32::try_from(r.integer(i)?).map_err(|_|"grid2d unsigned32 differs".into())}
fn flag(r:FloatRow<'_>,i:usize)->Result<bool,String>{match r.integer(i)?{0=>Ok(false),1=>Ok(true),_=>Err("grid2d boolean differs".into())}}
fn rows<'a>(d:&'a SqliteDatabase,t:&str,c:&mut SqliteSnapshotControl<'_>)->Result<Vec<FloatRow<'a>>,String>{let mut result=Vec::new();let mut seen=BTreeSet::new();for(i,r)in d.table(t)?.rows.iter().enumerate(){if i%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,i,0)?;}let r=FloatRow::new(r,floats(t))?;if !seen.insert(r.rowid){return Err("duplicate grid2d entity identity".into())}result.push(r);}Ok(result)}
fn ordered(mut rows:Vec<FloatRow<'_>>)->Result<Vec<FloatRow<'_>>,String>{rows.sort_by_key(|r|r.integer(2).unwrap_or(-1));for(i,r)in rows.iter().enumerate(){if r.integer(2)?!=ordinal(i)?{return Err("grid2d ordinals must be contiguous".into())}}Ok(rows)}
fn groups<'a>(d:&'a SqliteDatabase,t:&str,n:usize,owners:&BTreeSet<i64>,c:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,Vec<FloatRow<'a>>>,String>{let mut map=BTreeMap::<i64,Vec<FloatRow<'a>>>::new();for(i,r)in rows(d,t,c)?.into_iter().enumerate(){identity(r,n)?;let owner=r.integer(1)?;if !owners.contains(&owner){return Err("grid2d relationship has unknown owner".into())}map.entry(owner).or_default().push(r);if i%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,i,0)?;}}Ok(map)}
fn media<'a>(d:&'a SqliteDatabase,t:&str,n:usize,owners:&BTreeSet<i64>,c:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,FloatRow<'a>>,String>{let mut map=BTreeMap::new();for(i,r)in rows(d,t,c)?.into_iter().enumerate(){identity(r,n)?;if !owners.contains(&r.rowid){return Err("grid2d media has wrong-kind or unknown owner".into())}map.insert(r.rowid,r);if i%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,i,0)?;}}if map.len()!=owners.len(){return Err("grid2d media ownership is incomplete".into())}Ok(map)}
fn color(r:FloatRow<'_>,i:usize,owned:&mut Reconstruction<'_,'_>)->Result<WfcColor,String>{for _ in 0..4{owned.scalar()?;}Ok(WfcColor{r:word(r,i)?,g:word(r,i+1)?,b:word(r,i+2)?,a:word(r,i+3)?})}
fn point(r:FloatRow<'_>,i:usize,owned:&mut Reconstruction<'_,'_>)->Result<WfcPoint2,String>{owned.scalar()?;owned.scalar()?;Ok(WfcPoint2{x:r.real(i)?,y:r.real(i+1)?})}
fn direction(d:WfcDirection2d)->&'static str{match d{WfcDirection2d::Left=>"LEFT",WfcDirection2d::Right=>"RIGHT",WfcDirection2d::Top=>"TOP",WfcDirection2d::Bottom=>"BOTTOM"}}
fn color_cells(c:WfcColor)->[Cell<'static>;4]{[Cell::Integer(i64::from(c.r)),Cell::Integer(i64::from(c.g)),Cell::Integer(i64::from(c.b)),Cell::Integer(i64::from(c.a))]}
impl ArtifactSqliteSnapshot for Grid2dSnapshot{
const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
fn decode_sqlite_snapshot_native(payload:&store::io_schema::IoPayload,c:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{crate::schema::snapshot::text::decode_sqlite_snapshot_native(payload,c)}
fn encode_sqlite_snapshot_native(&self,encoding:SnapshotEncoding,c:&mut SqliteSnapshotControl<'_>)->Result<store::io_schema::IoPayload,String>{crate::schema::snapshot::text::encode_sqlite_snapshot_native(self,encoding,c)}
fn to_sqlite_database(&self,c:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,String>{
 let mut p=Projection::new(Self::SQLITE_SCHEMA,c)?;let mut count=1usize;for n in [self.tiles.len(),self.rules.len(),self.pinned.len(),self.masked.len()]{count=count.checked_add(n).ok_or("grid2d entity count overflow")?;p.check_rows(count)?;}for t in &self.tiles{count=count.checked_add(1).ok_or("grid2d media count overflow")?;p.check_rows(count)?;match &t.media{WfcTileMedia2d::Bitmap{palette,..}=>{count=count.checked_add(palette.len()).ok_or("grid2d palette count overflow")?;p.check_rows(count)?;},WfcTileMedia2d::Vector{paths}=>{count=count.checked_add(paths.len()).ok_or("grid2d path count overflow")?;p.check_rows(count)?;for path in paths{count=count.checked_add(path.segments.len()).and_then(|n|n.checked_add(usize::from(path.fill.is_some())+usize::from(path.stroke.is_some()))).ok_or("grid2d vector count overflow")?;p.check_rows(count)?;p.checkpoint()?;}},WfcTileMedia2d::Image{..}=>{}}p.checkpoint()?;}
 insert_key_ieee754(&mut p,"wfc_grid2d_document",1,&[Cell::Text(&self.schema),Cell::Text(&self.seed.to_string()),Cell::Integer(i64::from(self.width)),Cell::Integer(i64::from(self.height)),Cell::Real(self.cell_width),Cell::Real(self.cell_height),Cell::Integer(i64::from(self.periodic_x)),Cell::Integer(i64::from(self.periodic_y))],floats("wfc_grid2d_document"))?;
 for(i,t)in self.tiles.iter().enumerate(){let kind=match &t.media{WfcTileMedia2d::Bitmap{..}=>"bitmap",WfcTileMedia2d::Vector{..}=>"vector",WfcTileMedia2d::Image{..}=>"image"};let id=insert_ieee754(&mut p,"wfc_grid2d_tile",&[Cell::Integer(1),Cell::Integer(ordinal(i)?),Cell::Text(&t.id),t.label.as_deref().map_or(Cell::Null,Cell::Text),Cell::Real(t.weight),Cell::Text(kind)],floats("wfc_grid2d_tile"))?;
 match &t.media{WfcTileMedia2d::Bitmap{width,height,palette,pixels}=>{p.insert_key("wfc_grid2d_bitmap",id,&[Cell::Integer(i64::from(*width)),Cell::Integer(i64::from(*height)),Cell::Text(pixels)])?;for(i,v)in palette.iter().enumerate(){let q=color_cells(*v);p.insert("wfc_grid2d_palette",&[Cell::Integer(id),Cell::Integer(ordinal(i)?),q[0],q[1],q[2],q[3]])?;}},WfcTileMedia2d::Image{child}=>{let t=&child.target;p.insert_key("wfc_grid2d_image",id,&[Cell::Text(&child.child_id),Cell::Text(&t.artifact_id),Cell::Text(&t.dialect.artifact_kind),Cell::Text(&t.dialect.standard),Cell::Text(&t.dialect.subset)])?;},WfcTileMedia2d::Vector{paths}=>{p.insert_key("wfc_grid2d_vector",id,&[])?;for(i,path)in paths.iter().enumerate(){let path_id=insert_ieee754(&mut p,"wfc_grid2d_path",&[Cell::Integer(id),Cell::Integer(ordinal(i)?),Cell::Real(path.stroke_width)],floats("wfc_grid2d_path"))?;for(role,color)in [("fill",path.fill),("stroke",path.stroke)]{if let Some(v)=color{let q=color_cells(v);p.insert("wfc_grid2d_path_color",&[Cell::Integer(path_id),Cell::Text(role),q[0],q[1],q[2],q[3]])?;}}
 for(i,s)in path.segments.iter().enumerate(){let(kind,to,c1,c2)=match s{WfcPathSegment::MoveTo{to}=>("moveTo",Some(*to),None,None),WfcPathSegment::LineTo{to}=>("lineTo",Some(*to),None,None),WfcPathSegment::QuadTo{ctrl,to}=>("quadTo",Some(*to),Some(*ctrl),None),WfcPathSegment::CubicTo{ctrl1,ctrl2,to}=>("cubicTo",Some(*to),Some(*ctrl1),Some(*ctrl2)),WfcPathSegment::Close=>("close",None,None,None)};insert_ieee754(&mut p,"wfc_grid2d_segment",&[Cell::Integer(path_id),Cell::Integer(ordinal(i)?),Cell::Text(kind),to.map_or(Cell::Null,|v|Cell::Real(v.x)),to.map_or(Cell::Null,|v|Cell::Real(v.y)),c1.map_or(Cell::Null,|v|Cell::Real(v.x)),c1.map_or(Cell::Null,|v|Cell::Real(v.y)),c2.map_or(Cell::Null,|v|Cell::Real(v.x)),c2.map_or(Cell::Null,|v|Cell::Real(v.y))],floats("wfc_grid2d_segment"))?;}}}}
 }
 for(i,r)in self.rules.iter().enumerate(){p.insert("wfc_grid2d_rule",&[Cell::Integer(1),Cell::Integer(ordinal(i)?),Cell::Text(&r.id),Cell::Text(&r.tile_a_id),Cell::Text(&r.tile_b_id),Cell::Text(direction(r.direction)),Cell::Integer(i64::from(r.allowed))])?;}
 for(i,v)in self.pinned.iter().enumerate(){p.insert("wfc_grid2d_pin",&[Cell::Integer(1),Cell::Integer(ordinal(i)?),Cell::Integer(i64::from(v.x)),Cell::Integer(i64::from(v.y)),Cell::Text(&v.tile_id)])?;}for(i,v)in self.masked.iter().enumerate(){p.insert("wfc_grid2d_mask",&[Cell::Integer(1),Cell::Integer(ordinal(i)?),Cell::Integer(i64::from(v.x)),Cell::Integer(i64::from(v.y))])?;}p.finish()
}
fn from_sqlite_database(d:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{
 validate_sqlite_database_schema(d,Self::SQLITE_SCHEMA,c.limits()).map_err(|e|e.to_string())?;c.check_database(d,SqliteSnapshotPhase::ReconstructSnapshot)?;let doc=FloatRow::new(d.table("wfc_grid2d_document")?.single_row()?,floats("wfc_grid2d_document"))?;identity(doc,9)?;if doc.rowid!=1{return Err("grid2d root identity must be one".into())}let seed=doc.text(2)?.parse::<u64>().map_err(|_|"grid2d seed exceeds unsigned64")?;if seed.to_string()!=doc.text(2)?{return Err("grid2d seed requires canonical decimal".into())}
 let root=BTreeSet::from([1]);let tile_rows=ordered(groups(d,"wfc_grid2d_tile",7,&root,c)?.remove(&1).unwrap_or_default())?;let mut bitmap_ids=BTreeSet::new();let mut vector_ids=BTreeSet::new();let mut image_ids=BTreeSet::new();for(i,r)in tile_rows.iter().enumerate(){match r.text(6)?{"bitmap"=>{bitmap_ids.insert(r.rowid);},"vector"=>{vector_ids.insert(r.rowid);},"image"=>{image_ids.insert(r.rowid);},_=>return Err("grid2d media kind differs".into())}if i%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,i,0)?;}}
 let mut bitmaps=media(d,"wfc_grid2d_bitmap",4,&bitmap_ids,c)?;media(d,"wfc_grid2d_vector",1,&vector_ids,c)?;let mut images=media(d,"wfc_grid2d_image",6,&image_ids,c)?;let mut palettes=groups(d,"wfc_grid2d_palette",7,&bitmap_ids,c)?;let mut paths=groups(d,"wfc_grid2d_path",4,&vector_ids,c)?;let mut path_ids=BTreeSet::new();for(i,r)in d.table("wfc_grid2d_path")?.rows.iter().enumerate(){path_ids.insert(r.rowid);if i%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,i,0)?;}}let mut segments=groups(d,"wfc_grid2d_segment",10,&path_ids,c)?;let mut colors=BTreeMap::new();for(i,r)in rows(d,"wfc_grid2d_path_color",c)?.into_iter().enumerate(){identity(r,7)?;let owner=r.integer(1)?;let role=r.text(2)?;if !path_ids.contains(&owner)||!matches!(role,"fill"|"stroke")||colors.insert((owner,role),r).is_some(){return Err("grid2d path color role/ownership differs".into())}if i%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,i,0)?;}}
 let rule_rows=ordered(groups(d,"wfc_grid2d_rule",8,&root,c)?.remove(&1).unwrap_or_default())?;let pin_rows=ordered(groups(d,"wfc_grid2d_pin",6,&root,c)?.remove(&1).unwrap_or_default())?;let mask_rows=ordered(groups(d,"wfc_grid2d_mask",5,&root,c)?.remove(&1).unwrap_or_default())?;
 let mut owned=Reconstruction::new(c)?;for _ in 0..7{owned.scalar()?;}let schema=owned.text(doc.text(1)?)?;let mut tiles=Vec::new();for r in tile_rows{owned.scalar()?;let media=match r.text(6)?{"bitmap"=>{let v=bitmaps.remove(&r.rowid).ok_or("grid2d bitmap absent")?;owned.scalar()?;owned.scalar()?;let mut palette=Vec::new();for v in ordered(palettes.remove(&r.rowid).unwrap_or_default())?{palette.push(color(v,3,&mut owned)?);}WfcTileMedia2d::Bitmap{width:word(v,1)?,height:word(v,2)?,palette,pixels:owned.text(v.text(3)?)?}},"image"=>{let v=images.remove(&r.rowid).ok_or("grid2d image absent")?;WfcTileMedia2d::Image{child:store::ArtifactChild::new(owned.text(v.text(1)?)?,store::os_io::ArtifactRef{artifact_id:owned.text(v.text(2)?)?,dialect:store::os_io::ArtifactDialect{artifact_kind:owned.text(v.text(3)?)?,standard:owned.text(v.text(4)?)?,subset:owned.text(v.text(5)?)?}})}},"vector"=>{let mut native_paths=Vec::new();for v in ordered(paths.remove(&r.rowid).unwrap_or_default())?{let mut native_segments=Vec::new();for s in ordered(segments.remove(&v.rowid).unwrap_or_default())?{let kind=s.text(3)?;let present=match kind{"close"=>0,"moveTo"|"lineTo"=>2,"quadTo"=>4,"cubicTo"=>6,_=>return Err("grid2d segment kind differs".into())};for col in 4..10{if s.is_null(col)?!=(col>=4+present){return Err("grid2d segment point presence differs".into())}}let segment=match kind{"close"=>WfcPathSegment::Close,"moveTo"=>WfcPathSegment::MoveTo{to:point(s,4,&mut owned)?},"lineTo"=>WfcPathSegment::LineTo{to:point(s,4,&mut owned)?},"quadTo"=>WfcPathSegment::QuadTo{ctrl:point(s,6,&mut owned)?,to:point(s,4,&mut owned)?},"cubicTo"=>WfcPathSegment::CubicTo{ctrl1:point(s,6,&mut owned)?,ctrl2:point(s,8,&mut owned)?,to:point(s,4,&mut owned)?},_=>unreachable!()};native_segments.push(segment);owned.checkpoint()?;}let fill=colors.remove(&(v.rowid,"fill")).map(|r|color(r,3,&mut owned)).transpose()?;let stroke=colors.remove(&(v.rowid,"stroke")).map(|r|color(r,3,&mut owned)).transpose()?;owned.scalar()?;native_paths.push(WfcVectorPath{segments:native_segments,fill,stroke,stroke_width:v.real(3)?});}WfcTileMedia2d::Vector{paths:native_paths}},_=>unreachable!()};tiles.push(WfcTile2d{id:owned.text(r.text(3)?)?,label:r.optional_text(4)?.map(|s|owned.text(s)).transpose()?,weight:r.real(5)?,media});}
 let mut rules=Vec::new();for r in rule_rows{let direction=match r.text(6)?{"LEFT"=>WfcDirection2d::Left,"RIGHT"=>WfcDirection2d::Right,"TOP"=>WfcDirection2d::Top,"BOTTOM"=>WfcDirection2d::Bottom,_=>return Err("grid2d direction differs".into())};owned.scalar()?;owned.scalar()?;rules.push(WfcAdjacencyRule2d{id:owned.text(r.text(3)?)?,tile_a_id:owned.text(r.text(4)?)?,tile_b_id:owned.text(r.text(5)?)?,direction,allowed:flag(r,7)?});}
 let mut pinned=Vec::new();for r in pin_rows{owned.scalar()?;owned.scalar()?;pinned.push(WfcPinnedCell2d{x:word(r,3)?,y:word(r,4)?,tile_id:owned.text(r.text(5)?)?});}let mut masked=Vec::new();for r in mask_rows{owned.scalar()?;owned.scalar()?;masked.push(WfcCell2d{x:word(r,3)?,y:word(r,4)?});}owned.checkpoint()?;Ok(Self{schema,seed,width:word(doc,3)?,height:word(doc,4)?,cell_width:doc.real(5)?,cell_height:doc.real(6)?,periodic_x:flag(doc,7)?,periodic_y:flag(doc,8)?,tiles,rules,pinned,masked})
}
fn preflight_sqlite_snapshot_encoding(&self,_encoding:SnapshotEncoding,c:&mut SqliteSnapshotControl<'_>)->Result<(),String>{let mut b=NativeEncodingBound::new(c)?;b.add(16384)?;b.repeated(self.schema.len(),16)?;let mut count=1usize;for n in [self.tiles.len(),self.rules.len(),self.pinned.len(),self.masked.len()]{count=count.checked_add(n).ok_or("grid2d native count overflow")?;b.check_rows(count)?;}for t in &self.tiles{b.repeated(t.id.len(),16)?;if let Some(s)=&t.label{b.repeated(s.len(),16)?;}b.add(4096)?;match &t.media{WfcTileMedia2d::Bitmap{palette,pixels,..}=>{count=count.checked_add(palette.len()).ok_or("grid2d palette count overflow")?;b.check_rows(count)?;b.repeated(palette.len(),1024)?;b.repeated(pixels.len(),16)?;},WfcTileMedia2d::Vector{paths}=>{for path in paths{count=count.checked_add(1).and_then(|n|n.checked_add(path.segments.len())).ok_or("grid2d path count overflow")?;b.check_rows(count)?;b.add(4096)?;b.repeated(path.segments.len(),16384)?;}},WfcTileMedia2d::Image{child}=>{let t=&child.target;for s in [&child.child_id,&t.artifact_id,&t.dialect.artifact_kind,&t.dialect.standard,&t.dialect.subset]{b.repeated(s.len(),16)?;}}}}for r in &self.rules{for s in [&r.id,&r.tile_a_id,&r.tile_b_id]{b.repeated(s.len(),16)?;}b.add(1024)?;}for pin in &self.pinned{b.repeated(pin.tile_id.len(),16)?;b.add(1024)?;}b.repeated(self.masked.len(),512)?;b.finish()}
fn validate_sqlite_snapshot_subset(&self,dialect:&store::os_io::ArtifactDialect,d:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->semio_framework_os_kernel::io_schema::IoResult<()>{c.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,1)?;if dialect.artifact_kind!="s.wfc.grid2d"||dialect.standard!="1"||dialect.subset!="*"{return Err(String::from("grid2d dialect differs from its owned wildcard").into())}if d.table("wfc_grid2d_document")?.single_row()?.text(1)?!=self.schema{return Err(String::from("grid2d projected schema differs").into())}c.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,1,1)?;Ok(semio_framework_os_kernel::io_schema::IoOutcome::clean(()))}
}
